export default {"concepts":[{"id":"articles","name":"Articles (a / an / the)","hint":"Polish has no articles — English marks every countable noun.","count":29},{"id":"verb_tense","name":"Verb tenses","hint":"Time + aspect: simple, continuous, perfect.","count":21},{"id":"subject_verb","name":"Subject–verb agreement","hint":"Singular subjects take singular verbs.","count":18},{"id":"prepositions","name":"Prepositions","hint":"In, on, at, for, since… small words, big meaning.","count":21},{"id":"word_order","name":"Word order","hint":"English loves Subject–Verb–Object.","count":12},{"id":"plurals","name":"Plurals & countability","hint":"Much/many, information (no s!), irregular plurals.","count":13},{"id":"pronouns","name":"Pronouns","hint":"He/she/it, who/which, myself vs me.","count":7},{"id":"modals","name":"Modal verbs","hint":"Can, could, should, must — no -s, no to.","count":9},{"id":"conditionals","name":"Conditionals","hint":"If-clauses: real, unreal, and past unreal.","count":9},{"id":"comparatives","name":"Comparatives & superlatives","hint":"Bigger, more interesting, the best.","count":8},{"id":"gerund_infinitive","name":"Gerund vs infinitive","hint":"Enjoy doing, want to do, stop smoking vs stop to smoke.","count":8},{"id":"collocation","name":"Collocations","hint":"Words that belong together: make a decision, heavy rain.","count":11},{"id":"word_choice","name":"Word choice & false friends","hint":"Actually ≠ aktualnie. Eventually ≠ ewentualnie.","count":15},{"id":"questions_negation","name":"Questions & negation","hint":"Do-support: Do you like…? She doesn't know.","count":9}],"exercises":[{"id":"articles_6","concept":"articles","level":"A1","options":["I have cat","I have a cat","I have an cat"],"answerIndex":1,"explain":"Missing indefinite article before singular countable noun 'cat'"},{"id":"articles_11","concept":"articles","level":"A1","options":["He bought car","He bought an car","He bought a car"],"answerIndex":2,"explain":"Missing indefinite article before singular countable noun 'car'"},{"id":"articles_12","concept":"articles","level":"A1","options":["I read book","I read a book","I read an book"],"answerIndex":1,"explain":"Missing indefinite article before singular countable noun 'book'"},{"id":"articles_16","concept":"articles","level":"A1","options":["Sun is bright","The sun is bright","A sun is bright"],"answerIndex":1,"explain":"Missing definite article 'the' before unique celestial body 'sun'"},{"id":"articles_17","concept":"articles","level":"A1","options":["I want an apple","I want apple","I want a apple"],"answerIndex":0,"explain":"Missing indefinite article 'an' before vowel-sound word 'apple'"},{"id":"articles_19","concept":"articles","level":"A1","options":["He is engineer.","He is a engineer.","He is an engineer."],"answerIndex":2,"explain":"'an' before vowel sounds: an engineer, an hour."},{"id":"articles_24","concept":"articles","level":"A1","options":["I have a dog and a cat.","I have dog and cat.","I have dog and a cat."],"answerIndex":0,"explain":"Singular countable nouns need an article."},{"id":"articles_27","concept":"articles","level":"A1","options":["I saw an elephant","I saw elephant","I saw a elephant"],"answerIndex":0,"explain":"Missing indefinite article 'an' before vowel-initial word 'elephant'"},{"id":"articles_37","concept":"articles","level":"A1","options":["She has a dog","She has dog","She has an dog"],"answerIndex":0,"explain":"Missing indefinite article before singular countable noun 'dog'"},{"id":"articles_38","concept":"articles","level":"A1","options":["She is a teacher.","She is teacher.","She is an teacher."],"answerIndex":0,"explain":"Jobs take 'a/an': a teacher, an engineer."},{"id":"verb_tense_8","concept":"verb_tense","level":"A1","options":["She goed home yesterday.","She went home yesterday.","She has gone home yesterday."],"answerIndex":1,"explain":"Irregular past: go → went. 'Yesterday' forces past simple."},{"id":"verb_tense_21","concept":"verb_tense","level":"A1","options":["She works every Saturday.","She working every Saturday.","She work every Saturday."],"answerIndex":0,"explain":"Routine = present simple + third-person -s."},{"id":"verb_tense_39","concept":"verb_tense","level":"A1","options":["They have eat pizza last night.","They ate pizza last night.","They eated pizza last night."],"answerIndex":1,"explain":"Irregular past: eat → ate."},{"id":"subject_verb_0","concept":"subject_verb","level":"A1","options":["I working now","I am working now","I is working now"],"answerIndex":1,"explain":"Present continuous needs the auxiliary that matches the subject: I am working. Polish 'pracuję' has no auxiliary, so learners drop it."},{"id":"subject_verb_6","concept":"subject_verb","level":"A1","options":["She like coffee.","She likes coffee.","She liking coffee."],"answerIndex":1,"explain":"Third person singular adds -s: she likes."},{"id":"subject_verb_8","concept":"subject_verb","level":"A1","options":["There is two cats in the garden.","There are two cats in the garden.","There be two cats in the garden."],"answerIndex":1,"explain":"There are + plural."},{"id":"subject_verb_13","concept":"subject_verb","level":"A1","options":["He watchs TV every evening.","He watches TV every evening.","He watch TV every evening."],"answerIndex":1,"explain":"Verbs in -ch add -es: watches, teaches."},{"id":"subject_verb_16","concept":"subject_verb","level":"A1","options":["He don't know","He doesn't knows","He doesn't know"],"answerIndex":2,"explain":"Third person: doesn't + base verb (no second -s). Polish learners learn 'don't' first and use it for everyone."},{"id":"subject_verb_19","concept":"subject_verb","level":"A1","options":["She works here","She work here","She is works here"],"answerIndex":0,"explain":"Missing third-person singular 's' on present tense verb with singular subject"},{"id":"prepositions_10","concept":"prepositions","level":"A1","options":["The meeting is in Monday.","The meeting is on Monday.","The meeting is at Monday."],"answerIndex":1,"explain":"Days take ON: on Monday, on my birthday."},{"id":"prepositions_11","concept":"prepositions","level":"A1","options":["I was born in May.","I was born on May.","I was born at May."],"answerIndex":0,"explain":"Months take IN: in May, in winter, in 2020."},{"id":"prepositions_13","concept":"prepositions","level":"A1","options":["See you in six o'clock.","See you on six o'clock.","See you at six o'clock."],"answerIndex":2,"explain":"Clock times take AT: at six, at noon, at midnight."},{"id":"word_order_5","concept":"word_order","level":"A1","options":["Where she lives?","Where does she live?","Where does she lives?"],"answerIndex":1,"explain":"Questions need do/does, and after 'does' the verb loses its -s: Where does she live?"},{"id":"word_order_7","concept":"word_order","level":"A1","options":["I like big red apples.","I like apples big red.","I like red big apples."],"answerIndex":0,"explain":"Adjective order: size before colour — big red apples."},{"id":"word_order_13","concept":"word_order","level":"A1","options":["I tomorrow go","I am going tomorrow","I am tomorrow going"],"answerIndex":1,"explain":"Time words go at the end (or the very start), never between subject and verb: I am going tomorrow."},{"id":"word_order_15","concept":"word_order","level":"A1","options":["Where live you?","Where do you live?","Where you live?"],"answerIndex":1,"explain":"Questions need do-support: Where do you…?"},{"id":"word_order_26","concept":"word_order","level":"A1","options":["I also want to go","I want too to go","I want also to go"],"answerIndex":0,"explain":"'also' goes before the main verb: I also want to go. 'too' only works at the end: I want to go too."},{"id":"plurals_3","concept":"plurals","level":"A1","options":["My feets hurt.","My feet hurt.","My foots hurt."],"answerIndex":1,"explain":"Irregular plural: foot → feet."},{"id":"plurals_8","concept":"plurals","level":"A1","options":["I have three brothers.","I have three brotheres.","I have three brother."],"answerIndex":0,"explain":"Numbers force the plural: three brothers."},{"id":"plurals_9","concept":"plurals","level":"A1","options":["Two childrens are playing outside.","Two childs are playing outside.","Two children are playing outside."],"answerIndex":2,"explain":"Irregular plural: child → children."},{"id":"pronouns_1","concept":"pronouns","level":"A1","options":["This is me book. It's me.","This is mine book. It's my.","This is my book. It's mine."],"answerIndex":2,"explain":"my + noun; mine stands alone."},{"id":"pronouns_8","concept":"pronouns","level":"A1","options":["She and I went shopping.","She and me went shopping.","Her and me went shopping."],"answerIndex":0,"explain":"Subjects take she/I, not her/me."},{"id":"modals_12","concept":"modals","level":"A1","options":["She can to swim very well.","She cans swim very well.","She can swim very well."],"answerIndex":2,"explain":"Modals take the bare verb: can swim (no to, no -s)."},{"id":"comparatives_4","concept":"comparatives","level":"A1","options":["My car is bigger that yours.","My car is more big than yours.","My car is bigger than yours."],"answerIndex":2,"explain":"Short adjectives take -er … THAN."},{"id":"collocation_10","concept":"collocation","level":"A1","options":["In the morning I wake.","In the morning I wake up.","In the morning I wake on."],"answerIndex":1,"explain":"'wake up' is a phrasal verb; the particle 'up' is part of the meaning (Polish 'budzić się' is one verb)."},{"id":"questions_negation_1","concept":"questions_negation","level":"A1","options":["What do you want?","What you want?","What does you want?"],"answerIndex":0,"explain":"Questions need do/does: What do you want? Polish asks with intonation alone ('Co chcesz?'), so the auxiliary is easy to leave out."},{"id":"questions_negation_2","concept":"questions_negation","level":"A1","options":["I not know","I don't know","He don't know"],"answerIndex":1,"explain":"Negation requires auxiliary 'do'; 'not' cannot directly negate main verb"},{"id":"questions_negation_6","concept":"questions_negation","level":"A1","options":["Is there a bank near here?","There is a bank near here?","Is it a bank near here?"],"answerIndex":0,"explain":"Invert there is → Is there…?"},{"id":"questions_negation_7","concept":"questions_negation","level":"A1","options":["She doesn't likes tea.","She doesn't like tea.","She don't like tea."],"answerIndex":1,"explain":"Third person: doesn't + base verb."},{"id":"questions_negation_9","concept":"questions_negation","level":"A1","options":["Like you coffee?","Do you like coffee?","You like coffee?"],"answerIndex":1,"explain":"Yes/no questions need do/does."},{"id":"articles_3","concept":"articles","level":"A2","options":["A sun rises in an east.","Sun rises in east.","The sun rises in the east."],"answerIndex":2,"explain":"Unique things take 'the': the sun, the sky."},{"id":"articles_5","concept":"articles","level":"A2","options":["I went to store yesterday.","I went to an store yesterday.","I went to the store yesterday."],"answerIndex":2,"explain":"A place both speakers know takes 'the': the store, the station. Polish has no article to drop, so the bare noun feels complete but is not."},{"id":"articles_8","concept":"articles","level":"A2","options":["I want to become a doctor.","I want to become an doctor.","I want to become doctor."],"answerIndex":0,"explain":"Jobs take a/an even after 'become': become a doctor. Polish 'zostać lekarzem' has no article, so learners drop it."},{"id":"articles_9","concept":"articles","level":"A2","options":["She is teacher at my school.","She is a teacher at my school.","She is an teacher at my school."],"answerIndex":1,"explain":"Jobs take a/an: a teacher, an engineer. Polish has no articles, so 'teacher' alone feels complete but is not."},{"id":"articles_13","concept":"articles","level":"A2","options":["She works in office.","She works in a office.","She works in an office."],"answerIndex":2,"explain":"Singular countable nouns need an article, and 'an' before a vowel sound: an office. Polish has no articles, so learners omit them."},{"id":"articles_14","concept":"articles","level":"A2","options":["At the weekend, I go to the cinema.","In weekend I go to cinema.","At the weekend, I go to cinema."],"answerIndex":0,"explain":"'The cinema' takes 'the' even in general (like 'the theatre', 'the gym'). Polish 'w weekend' has no article, so both get dropped."},{"id":"articles_15","concept":"articles","level":"A2","options":["I go to work by bus.","I go to work by a bus.","I go to the work by bus."],"answerIndex":0,"explain":"Transport: by bus/car/train — no article."},{"id":"articles_18","concept":"articles","level":"A2","options":["She is very nice person.","She is a very nice person.","She is an very nice person."],"answerIndex":1,"explain":"a + adjective + noun: a very nice person. Polish has no articles, so the whole phrase feels complete without one."},{"id":"articles_22","concept":"articles","level":"A2","options":["I am student from Poland.","I am a student from Poland.","I am an student from Poland."],"answerIndex":1,"explain":"Polish lacks articles entirely. Polish speakers must consciously add 'a/an' before singular countable nouns in predicative position (after 'be')."},{"id":"articles_25","concept":"articles","level":"A2","options":["We had the lunch at noon.","We had lunch at noon.","We had a lunch at noon."],"answerIndex":1,"explain":"Meals take no article: have breakfast, eat dinner."},{"id":"articles_28","concept":"articles","level":"A2","options":["She plays a piano.","She plays the piano.","She plays piano."],"answerIndex":1,"explain":"Instruments take 'the': play the piano/guitar."},{"id":"articles_29","concept":"articles","level":"A2","options":["When I am older, I will have a house.","When I am older, I will have house.","When I am older, I will have an house."],"answerIndex":0,"explain":"A new, singular countable thing takes 'a': a house. Polish has no article to drop, so the bare noun feels finished but is not."},{"id":"articles_33","concept":"articles","level":"A2","options":["This is a accurate translation.","This is an accurate translation.","This is accurate translation."],"answerIndex":1,"explain":"Singular countable nouns need an article, and 'an' before a vowel sound: an accurate translation."},{"id":"articles_34","concept":"articles","level":"A2","options":["Today is a rainy day.","Today is rainy day.","Today rainy day."],"answerIndex":0,"explain":"English needs both the verb 'is' and the article: Today is a rainy day. Polish 'Dziś deszczowy dzień' has neither."},{"id":"articles_35","concept":"articles","level":"A2","options":["I saw the film. A film was great.","I saw a film. The film was great.","I saw film. Film was great."],"answerIndex":1,"explain":"First mention 'a', known thing 'the'."},{"id":"verb_tense_0","concept":"verb_tense","level":"A2","options":["I working every day.","I work every day.","I am work every day."],"answerIndex":1,"explain":"Routine = present simple: I work. Polish 'Pracuję' is one word, so learners either drop 'am' from a continuous form or add it to a simple one."},{"id":"verb_tense_4","concept":"verb_tense","level":"A2","options":["I didn't wake up early today.","I didn't woke up early today.","I don't wake up early today."],"answerIndex":0,"explain":"A finished action earlier today takes past simple: didn't + base verb (wake, not woke). Polish uses the present for 'today' events."},{"id":"verb_tense_7","concept":"verb_tense","level":"A2","options":["I have had a party yesterday.","I had a party yesterday.","I have a party yesterday."],"answerIndex":1,"explain":"'Yesterday' is finished time, so past simple: had. Never present perfect with yesterday."},{"id":"verb_tense_10","concept":"verb_tense","level":"A2","options":["She have been working here.","She has been working here.","She is been working here."],"answerIndex":1,"explain":"Present perfect continuous with she/he/it: has been + -ing."},{"id":"verb_tense_17","concept":"verb_tense","level":"A2","options":["I didn't went there.","I didn't go there.","I didn't gone there."],"answerIndex":1,"explain":"After didn't the verb goes back to its base form: didn't go. Polish marks the past on the verb itself (nie poszedłem), so learners mark it twice."},{"id":"verb_tense_18","concept":"subject_verb","level":"A2","options":["They have many problems.","They has many problems.","They haves many problems."],"answerIndex":0,"explain":"Only he/she/it takes 'has'; they have. Polish 'oni mają' looks the same for every plural subject, so the -s rule is easy to forget."},{"id":"verb_tense_23","concept":"verb_tense","level":"A2","options":["He was watching TV when I called.","He watched TV when I was calling.","He watching TV when I called."],"answerIndex":0,"explain":"Long action = past continuous; interruption = past simple."},{"id":"verb_tense_25","concept":"verb_tense","level":"A2","options":["Water is boiling at 100 degrees every time.","Water boils at 100 degrees.","Water boil at 100 degrees."],"answerIndex":1,"explain":"Facts take present simple."},{"id":"verb_tense_26","concept":"verb_tense","level":"A2","options":["I go yesterday","I went yesterday","I goed yesterday"],"answerIndex":1,"explain":"'Yesterday' forces past simple, and go is irregular: went."},{"id":"verb_tense_29","concept":"verb_tense","level":"A2","options":["People works in this country.","People working in this country.","People work in this country."],"answerIndex":2,"explain":"'People' is plural: people work. A sentence also needs a finite verb, so 'working' alone is not enough."},{"id":"verb_tense_32","concept":"verb_tense","level":"A2","options":["Did you saw the match last night?","Have you seen the match last night?","Did you see the match last night?"],"answerIndex":2,"explain":"Finished time ('last night') = past simple; did + base verb."},{"id":"verb_tense_33","concept":"verb_tense","level":"A2","options":["I live here since 2019.","I am living here since 2019.","I have lived here since 2019."],"answerIndex":2,"explain":"'since' + present perfect: have lived."},{"id":"verb_tense_35","concept":"verb_tense","level":"A2","options":["I've waiting for him since morning.","I've been waiting for him since morning.","I'm waiting for him since morning."],"answerIndex":1,"explain":"since + present perfect continuous: have been waiting. Polish uses the present with 'od' (since), which pulls learners to 'I'm waiting'."},{"id":"verb_tense_37","concept":"verb_tense","level":"A2","options":["She came to the party tomorrow.","She come to the party tomorrow.","She is coming to the party tomorrow."],"answerIndex":2,"explain":"Arranged future: present continuous (is coming)."},{"id":"verb_tense_38","concept":"verb_tense","level":"A2","options":["I done it","I did it","I have did it"],"answerIndex":1,"explain":"did = past simple, done = past participle (have done). Simple past on its own: I did it."},{"id":"verb_tense_40","concept":"subject_verb","level":"A2","options":["My brother has my bike.","My brother have my bike.","My brother is have my bike."],"answerIndex":0,"explain":"he/she/it (my brother) takes 'has'. Polish 'mieć' looks the same for every person, so the -s is easy to miss."},{"id":"subject_verb_1","concept":"subject_verb","level":"A2","options":["My family living in Warsaw.","My family lives in Warsaw.","My family are live in Warsaw."],"answerIndex":1,"explain":"Collective nouns usually take a singular verb (US/neutral)."},{"id":"subject_verb_10","concept":"subject_verb","level":"A2","options":["Everyone are here.","Everyone be here.","Everyone is here."],"answerIndex":2,"explain":"'Everyone/everybody' is singular."},{"id":"subject_verb_11","concept":"subject_verb","level":"A2","options":["Each students has a locker.","Each student have a locker.","Each student has a locker."],"answerIndex":2,"explain":"'Each' + singular noun + singular verb."},{"id":"subject_verb_15","concept":"subject_verb","level":"A2","options":["She don't like coffee.","She doesn't like coffee.","She doesn't likes coffee."],"answerIndex":1,"explain":"Polish lacks auxiliary 'do' and has no equivalent of 'doesn't'. Polish speakers learn 'don't' first and overgeneralize it to all persons."},{"id":"subject_verb_17","concept":"subject_verb","level":"A2","options":["They was happy","They is happy","They were happy"],"answerIndex":2,"explain":"Plural subjects take 'were': they were. Polish 'byli' does not change the auxiliary, so was/were is easy to mix up."},{"id":"subject_verb_18","concept":"subject_verb","level":"A2","options":["She has finished","She haves finished","She have finished"],"answerIndex":0,"explain":"Third person singular takes 'has': she has finished."},{"id":"prepositions_3","concept":"prepositions","level":"A2","options":["Can you explain me one more time?","Can you explain to me one more time?","Can you explain at me one more time?"],"answerIndex":1,"explain":"explain something TO someone. Polish 'wyjaśnić mi' needs no preposition, which is why 'explain me' feels right."},{"id":"prepositions_5","concept":"prepositions","level":"A2","options":["We waited for the bus.","We waited the bus.","We waited to the bus."],"answerIndex":0,"explain":"wait FOR something/someone."},{"id":"prepositions_6","concept":"prepositions","level":"A2","options":["I'm interested in this topic.","I'm interested on this topic.","I'm interested for this topic."],"answerIndex":0,"explain":"interested IN. Polish 'zainteresowany czymś' uses a case ending, not a preposition, so any English preposition feels equally likely."},{"id":"prepositions_12","concept":"prepositions","level":"A2","options":["She is good at maths.","She is good in maths.","She is good on maths."],"answerIndex":0,"explain":"good AT something."},{"id":"prepositions_15","concept":"prepositions","level":"A2","options":["I depend on my parents.","I depend of my parents.","I depend from my parents."],"answerIndex":0,"explain":"depend ON. Polish 'zależeć od' ('from') is why 'depend from' feels natural."},{"id":"prepositions_16","concept":"prepositions","level":"A2","options":["I'm listening at music.","I'm listening music.","I'm listening to music."],"answerIndex":2,"explain":"listen TO something."},{"id":"prepositions_18","concept":"prepositions","level":"A2","options":["It depends of the weather.","It depends on the weather.","It depends from the weather."],"answerIndex":1,"explain":"depend ON (Polish: zależeć od → tempting \"from\")."},{"id":"prepositions_21","concept":"prepositions","level":"A2","options":["I have been here from Monday.","I have been here since Monday.","I have been here since three days."],"answerIndex":1,"explain":"SINCE + starting point; FOR + duration."},{"id":"prepositions_29","concept":"prepositions","level":"A2","options":["I'm afraid at dogs.","I'm afraid from dogs.","I'm afraid of dogs."],"answerIndex":2,"explain":"afraid OF. Polish 'bać się czegoś' uses a case ending, so learners guess a preposition; 'from' comes from 'od'."},{"id":"prepositions_33","concept":"prepositions","level":"B1","options":["We discussed about political reality.","We discussed political reality.","We discussed on political reality."],"answerIndex":1,"explain":"'discuss' takes its object directly: discuss something (but talk ABOUT something). Polish 'dyskutować o' has a preposition, English does not."},{"id":"word_order_2","concept":"word_order","level":"A2","options":["She always drinks tea in the morning.","She drinks tea always in the morning.","She drinks always tea in the morning."],"answerIndex":0,"explain":"Frequency adverbs go before the main verb: always, often, never."},{"id":"word_order_4","concept":"word_order","level":"A2","options":["She gave to me the book.","She me gave the book.","She gave me the book."],"answerIndex":2,"explain":"Indirect object before direct: gave me the book."},{"id":"word_order_9","concept":"word_order","level":"A2","options":["He speaks very well English.","He speaks English very well.","He very well speaks English."],"answerIndex":1,"explain":"Manner adverbs come after the object: speaks English well."},{"id":"word_order_16","concept":"word_order","level":"A2","options":["I like really this city.","Really I like very this city.","I really like this city."],"answerIndex":2,"explain":"Adverbs of degree go before the verb, not after."},{"id":"plurals_1","concept":"plurals","level":"A2","options":["Her advice were very useful.","Her advice was very useful.","Her advices were very useful."],"answerIndex":1,"explain":"'Advice' is uncountable: a piece of advice."},{"id":"plurals_4","concept":"plurals","level":"A2","options":["He has a big progress.","He has made a good progress.","He has made good progress."],"answerIndex":2,"explain":"'progress' is uncountable, so never 'a progress'. Polish 'ma duży postęp' invites the article and the wrong verb."},{"id":"plurals_5","concept":"plurals","level":"A2","options":["I bought two loafs of bread.","I bought two loaves of bread.","I bought two breads."],"answerIndex":1,"explain":"Bread is uncountable: a loaf/two loaves of bread."},{"id":"plurals_10","concept":"plurals","level":"A2","options":["How much money do you have?","How many money do you have?","How much moneys do you have?"],"answerIndex":0,"explain":"much + uncountable (money), many + countable (coins)."},{"id":"plurals_11","concept":"plurals","level":"A2","options":["Can you give me some informations?","Can you give me an information?","Can you give me some information?"],"answerIndex":2,"explain":"'Information' is uncountable — never 'informations'."},{"id":"plurals_13","concept":"plurals","level":"A2","options":["She gave me a lot of advices.","She gave me a lot of advice.","She gave me a lot of advises."],"answerIndex":1,"explain":"'advice' is uncountable: never 'advices'. (Same for information, furniture, news.)"},{"id":"plurals_17","concept":"prepositions","level":"A2","options":["He is responsible for this.","He is responsible of this.","He is responsible about this."],"answerIndex":0,"explain":"responsible FOR. Polish 'odpowiedzialny za' maps to 'for'."},{"id":"pronouns_2","concept":"pronouns","level":"A2","options":["Everybody brought his own lunches.","Everybody brought their own lunch.","Everybody brought its own lunch."],"answerIndex":1,"explain":"Singular 'they' is the natural choice for everybody/someone."},{"id":"pronouns_3","concept":"pronouns","level":"A2","options":["Between you and I, it's a secret.","Between you and me, it's a secret.","Between we, it's a secret."],"answerIndex":1,"explain":"After prepositions use object pronouns: between you and me."},{"id":"pronouns_5","concept":"pronouns","level":"A2","options":["The woman which lives next door is a nurse.","The woman who lives next door is a nurse.","The woman what lives next door is a nurse."],"answerIndex":1,"explain":"who = people, which = things."},{"id":"modals_4","concept":"modals","level":"A2","options":["You must not smoke here.","You don't must smoke here.","You must not to smoke here."],"answerIndex":0,"explain":"Negate the modal itself: must not / mustn't."},{"id":"modals_6","concept":"modals","level":"A2","options":["Could you opening the window, please?","Could you open the window, please?","Could you to open the window, please?"],"answerIndex":1,"explain":"could + base verb for polite requests."},{"id":"modals_15","concept":"modals","level":"A2","options":["You should to see a doctor.","You should see a doctor.","You should seeing a doctor."],"answerIndex":1,"explain":"should + base verb."},{"id":"conditionals_2","concept":"conditionals","level":"A2","options":["If you heated ice, it melts.","If you heat ice, it will melted.","If you heat ice, it melts."],"answerIndex":2,"explain":"Zero conditional (facts): if + present, present."},{"id":"conditionals_3","concept":"conditionals","level":"A2","options":["If it rains, we would stayed home.","If it will rain, we will stay home.","If it rains, we will stay home."],"answerIndex":2,"explain":"First conditional: if + present, will + verb (no 'will' after if)."},{"id":"comparatives_1","concept":"comparatives","level":"A2","options":["This film is interestinger than the book.","This film is more interesting than the book.","This film is more interesting from the book."],"answerIndex":1,"explain":"Long adjectives take more … than."},{"id":"comparatives_3","concept":"comparatives","level":"A2","options":["He is as tall than his father.","He is as tall as his father.","He is so tall as his father."],"answerIndex":1,"explain":"Equality: as + adjective + as."},{"id":"comparatives_7","concept":"comparatives","level":"A2","options":["She is the most good student in the class.","She is the goodest student in the class.","She is the best student in the class."],"answerIndex":2,"explain":"Irregular: good → better → the best."},{"id":"gerund_infinitive_0","concept":"gerund_infinitive","level":"A2","options":["She decided moving abroad.","She decided move abroad.","She decided to move abroad."],"answerIndex":2,"explain":"decide + to + verb."},{"id":"gerund_infinitive_1","concept":"gerund_infinitive","level":"A2","options":["It's worth visiting the museum.","It's worth visit the museum.","It's worth to visit the museum."],"answerIndex":0,"explain":"worth + -ing."},{"id":"gerund_infinitive_2","concept":"gerund_infinitive","level":"A2","options":["She wants learning Spanish.","She wants learn Spanish.","She wants to learn Spanish."],"answerIndex":2,"explain":"want + to + verb."},{"id":"gerund_infinitive_3","concept":"gerund_infinitive","level":"A2","options":["I enjoy to read books.","I enjoy reading books.","I enjoy read books."],"answerIndex":1,"explain":"enjoy + -ing."},{"id":"collocation_1","concept":"collocation","level":"A2","options":["I did a mistake.","I made a mistake.","I maked a mistake."],"answerIndex":1,"explain":"Polish uses 'zrobić błąd' (do/make a mistake interchangeably), but English has fixed collocations."},{"id":"collocation_5","concept":"collocation","level":"A2","options":["Can I do a suggestion?","Can I make a suggestion?","Can I put a suggestion on?"],"answerIndex":1,"explain":"MAKE a suggestion/decision/mistake."},{"id":"collocation_6","concept":"collocation","level":"A2","options":["She did a photo of the bridge.","She made a photo of the bridge.","She took a photo of the bridge."],"answerIndex":2,"explain":"TAKE a photo."},{"id":"collocation_8","concept":"collocation","level":"A2","options":["I have to catch the early train.","I have to catch up the early train.","I have to take up the early train."],"answerIndex":0,"explain":"CATCH a train/bus (catch up = dogonić)."},{"id":"word_choice_2","concept":"word_choice","level":"A2","options":["Can you borrow me some money?","Can you lend from me some money?","Can you lend me some money?"],"answerIndex":2,"explain":"lend = give temporarily; borrow = take temporarily."},{"id":"word_choice_3","concept":"word_choice","level":"A2","options":["I made my homework.","I did my homework.","I did make my homeworks."],"answerIndex":1,"explain":"DO homework (not make)."},{"id":"word_choice_5","concept":"word_choice","level":"A2","options":["She has a very nice flat.","She has a very sympathy flat.","She has a very sympathetic flat."],"answerIndex":0,"explain":"'sympatyczny' = nice/friendly; sympathetic = współczujący."},{"id":"word_choice_6","concept":"word_choice","level":"A2","options":["I have 25 years old.","I am 25 years old.","I have 25 years."],"answerIndex":1,"explain":"Polish uses 'mieć' (have) with age: 'mam 25 lat' (I have 25 years)."},{"id":"word_choice_8","concept":"word_choice","level":"A2","options":["I'm excited about the trip.","I'm excite about the trip.","I'm exciting about the trip."],"answerIndex":0,"explain":"People FEEL -ed: excited, interested, tired."},{"id":"word_choice_16","concept":"word_choice","level":"A2","options":["Let me tell you something.","Let me say you something.","Let me tell to you something."],"answerIndex":0,"explain":"tell + person (tell you), say + words (say something). Polish 'powiedzieć ci coś' is one verb for both."},{"id":"word_choice_21","concept":"word_choice","level":"A2","options":["I'm actually working from home.","I'm currently working from home.","I'm actual working from home."],"answerIndex":1,"explain":"False friend: Polish 'aktualnie' = currently. English 'actually' means 'in fact', so the first sentence says something different.","prompt":"You want to say that at the moment you work from home. Which is right?"},{"id":"word_choice_24","concept":"word_choice","level":"A2","options":["I learnt me a lot from that course.","I learned a lot from that course.","I teached myself a lot from that course."],"answerIndex":1,"explain":"learn = receive knowledge; teach = give it (taught, not teached)."},{"id":"word_choice_29","concept":"word_choice","level":"A2","options":["I feel sorry about this.","I feel pathetic about this.","I feel sorry for about this."],"answerIndex":0,"explain":"False friend: Polish 'patetyczny' (solemn, moving) is not English 'pathetic' (pitiful, useless). To express regret say 'I feel sorry about this'.","prompt":"You want to say you are sad about something. Which is right?"},{"id":"word_choice_31","concept":"word_choice","level":"A2","options":["Currently, I'm very tired.","Actually, I'm very tired.","Actual, I'm very tired."],"answerIndex":0,"explain":"False friend: Polish 'aktualnie' = currently (at present). English 'actually' = in fact. 'Actually, I'm very tired' is good English but says something else.","prompt":"You want to say that at the moment you are very tired. Which is right?"},{"id":"questions_negation_3","concept":"questions_negation","level":"A2","options":["What you did yesterday?","What did you did yesterday?","What did you do yesterday?"],"answerIndex":2,"explain":"did + base verb: What did you do?"},{"id":"questions_negation_5","concept":"collocation","level":"A2","options":["I did an appointment.","I made an appointment.","I took an appointment."],"answerIndex":1,"explain":"MAKE an appointment (and plans, decisions, mistakes). Polish 'zrobić' covers both make and do."},{"id":"questions_negation_11","concept":"questions_negation","level":"A2","options":["I didn't saw anything.","I didn't see nothing.","I didn't see anything."],"answerIndex":2,"explain":"One negative only: didn't see anything (not 'nothing')."},{"id":"articles_1","concept":"articles","level":"B1","options":["He is in hospital with a broken leg.","He is in a hospital with a broken leg.","He is in hospitals with a broken leg."],"answerIndex":0,"explain":"British English: in hospital (as a patient), in prison, at school, no article. Americans say 'in the hospital'."},{"id":"articles_21","concept":"articles","level":"B1","options":["The Netherlands is in Europe.","Netherlands is in Europe.","The Netherlands is in the Europe."],"answerIndex":0,"explain":"Plural country names take 'the'; continents don't."},{"id":"articles_23","concept":"articles","level":"B1","options":["I love a music.","I love musics.","I love music."],"answerIndex":2,"explain":"General uncountables take no article: music, love, water."},{"id":"verb_tense_1","concept":"verb_tense","level":"B1","options":["By 2030 I will finish already my studies.","By 2030 I will have finished my studies.","By 2030 I have finished my studies."],"answerIndex":1,"explain":"Future perfect for a deadline: will have finished."},{"id":"verb_tense_20","concept":"verb_tense","level":"B1","options":["I have already see that film.","I have already seen that film.","I have already saw that film."],"answerIndex":1,"explain":"Present perfect: have + past participle (seen, not saw)."},{"id":"verb_tense_27","concept":"verb_tense","level":"B1","options":["I used to smoke, but I quit.","I use to smoke, but I quit.","I was used to smoke, but I quit."],"answerIndex":0,"explain":"Past habit: used to + infinitive."},{"id":"subject_verb_2","concept":"subject_verb","level":"B1","options":["Politics are a difficult subject.","Politics is a difficult subject.","Politic is a difficult subject."],"answerIndex":1,"explain":"Subjects in -ics (politics, physics) are singular."},{"id":"subject_verb_4","concept":"subject_verb","level":"B1","options":["The news be good today.","The news is good today.","The news are good today."],"answerIndex":1,"explain":"'News' looks plural but is singular."},{"id":"subject_verb_12","concept":"subject_verb","level":"B1","options":["Neither of them wanting to go.","Neither of them want to go.","Neither of them wants to go."],"answerIndex":2,"explain":"'Neither of' takes a singular verb."},{"id":"prepositions_0","concept":"prepositions","level":"B1","options":["I'm married to a doctor.","I'm married on a doctor.","I'm married with a doctor."],"answerIndex":0,"explain":"married TO (Polish: z kimś → tempting \"with\")."},{"id":"prepositions_14","concept":"prepositions","level":"B1","options":["I agree at you","I agree with you","I agree to you"],"answerIndex":1,"explain":"agree WITH a person (agree TO a proposal). Polish 'zgadzać się z' matches 'with'."},{"id":"prepositions_17","concept":"prepositions","level":"B1","options":["She arrived in London on Friday.","She arrived at London in Friday.","She arrived to London on Friday."],"answerIndex":0,"explain":"arrive IN a city, AT a building."},{"id":"prepositions_26","concept":"prepositions","level":"B1","options":["He is interested with history.","He is interested in history.","He is interested about history."],"answerIndex":1,"explain":"interested IN something."},{"id":"word_order_14","concept":"word_order","level":"B1","options":["I don't know where lives he.","I don't know where does he live.","I don't know where he lives."],"answerIndex":2,"explain":"Indirect questions use statement order: where he lives."},{"id":"word_order_17","concept":"word_order","level":"B1","options":["Could you tell me what time is it?","Could you tell me what time it is?","Could you tell me what is it time?"],"answerIndex":1,"explain":"Embedded question = statement order: what time it is."},{"id":"plurals_2","concept":"plurals","level":"B1","options":["I have very much work","I have a lot of work","I have a lot of works"],"answerIndex":1,"explain":"'work' (a job, tasks) is uncountable: a lot of work, not 'works' and not 'very much work' in an affirmative sentence."},{"id":"plurals_6","concept":"plurals","level":"B1","options":["Fewer traffic is these days.","Less people smoke these days.","Fewer people smoke these days."],"answerIndex":2,"explain":"fewer + countable (people), less + uncountable (time)."},{"id":"plurals_12","concept":"plurals","level":"B1","options":["There is too many traffic today.","There is too much traffic today.","There are too many traffics today."],"answerIndex":1,"explain":"'Traffic' is uncountable: much traffic."},{"id":"plurals_14","concept":"plurals","level":"B1","options":["The furnitures in this room are old.","A furniture in this room is old.","The furniture in this room is old."],"answerIndex":2,"explain":"'Furniture' is uncountable: a piece of furniture."},{"id":"pronouns_0","concept":"pronouns","level":"B1","options":["The car who window is broken is mine.","The car whose window is broken is mine.","The car which window is broken is mine."],"answerIndex":1,"explain":"Possession uses 'whose' — even for things."},{"id":"pronouns_6","concept":"pronouns","level":"B1","options":["I enjoyed myself at the party.","I enjoyed self at the party.","I enjoyed me at the party."],"answerIndex":0,"explain":"enjoy ONESELF: I enjoyed myself."},{"id":"modals_1","concept":"modals","level":"B1","options":["You don't must come if you're busy.","You mustn't come if you're busy.","You don't have to come if you're busy."],"answerIndex":2,"explain":"don't have to = not necessary; mustn't = forbidden.","prompt":"Which sentence tells a friend that coming is optional?"},{"id":"modals_2","concept":"modals","level":"B1","options":["We might go to Spain this summer.","We might to go to Spain this summer.","We might going to Spain this summer."],"answerIndex":0,"explain":"might + base verb = possibility."},{"id":"modals_8","concept":"modals","level":"A1","options":["I will going","I will go","I will to go"],"answerIndex":1,"explain":"will + base verb: will go. No -ing and no 'to' after a modal."},{"id":"modals_9","concept":"modals","level":"B1","options":["I must worked late yesterday.","I musted work late yesterday.","I had to work late yesterday."],"answerIndex":2,"explain":"Past of must (obligation) = had to."},{"id":"conditionals_0","concept":"conditionals","level":"B1","options":["If I had more money, I will travelled.","If I would have more money, I would travel.","If I had more money, I would travel."],"answerIndex":2,"explain":"Second conditional: if + past, would + verb."},{"id":"conditionals_4","concept":"conditionals","level":"B1","options":["Unless you hurry, you'll miss the bus.","Unless you don't hurry, you'll miss the bus.","Unless you will hurry, you'll miss the bus."],"answerIndex":0,"explain":"unless = if not — don't add another negative."},{"id":"comparatives_0","concept":"comparatives","level":"B1","options":["The weather is getting worser and worser.","The weather is getting more and more bad.","The weather is getting worse and worse."],"answerIndex":2,"explain":"Irregular: bad → worse → the worst."},{"id":"comparatives_6","concept":"comparatives","level":"B1","options":["The more you practise, the easier it gets.","More you practise, easier it gets.","The more you practise, it gets easier much."],"answerIndex":0,"explain":"Parallel comparatives: 'the more…, the easier…'."},{"id":"gerund_infinitive_4","concept":"gerund_infinitive","level":"B1","options":["He stopped to smoke last year.","He stopped smoking last year.","He stopped smoke last year."],"answerIndex":1,"explain":"stop + -ing = quit; stop + to = pause in order to.","prompt":"Which sentence means he quit?"},{"id":"gerund_infinitive_5","concept":"gerund_infinitive","level":"B1","options":["I look forward to seeing you.","I look forward to see you.","I look forward seeing you."],"answerIndex":0,"explain":"'look forward to' + -ing (the 'to' is a preposition!)."},{"id":"gerund_infinitive_9","concept":"gerund_infinitive","level":"B1","options":["Would you mind open the window?","Would you mind to open the window?","Would you mind opening the window?"],"answerIndex":2,"explain":"mind + -ing."},{"id":"collocation_0","concept":"collocation","level":"B1","options":["He paid attention to the details.","He put attention to the details.","He took attention at the details."],"answerIndex":0,"explain":"PAY attention."},{"id":"collocation_2","concept":"collocation","level":"B1","options":["It was raining hardly all night.","It was raining heavily all night.","It was raining strongly all night."],"answerIndex":1,"explain":"heavy rain / raining heavily (and 'hardly' means almost not!)."},{"id":"collocation_9","concept":"collocation","level":"B1","options":["Let's hold in touch.","Let's keep in touch.","Let's stay in touching."],"answerIndex":1,"explain":"KEEP in touch / stay in touch."},{"id":"collocation_11","concept":"collocation","level":"B1","options":["They made their best to help.","They did their best to help.","They put their best to help."],"answerIndex":1,"explain":"DO your best."},{"id":"word_choice_13","concept":"word_choice","level":"B1","options":["We can take the bus, or eventually a taxi.","We can take the bus, or eventual a taxi.","We can take the bus, or possibly a taxi."],"answerIndex":2,"explain":"'ewentualnie' = possibly/alternatively, NOT eventually (= in the end)."},{"id":"word_choice_18","concept":"word_choice","level":"B1","options":["He made a big mistake.","He did a big mistake.","He maked a big mistake."],"answerIndex":0,"explain":"MAKE a mistake (not do). Collocations!"},{"id":"word_choice_22","concept":"word_choice","level":"B1","options":["She gave me some useful advices.","She said me some useful advice.","She gave me some useful advice."],"answerIndex":2,"explain":"advice is uncountable; and it's 'tell me', not 'say me'."},{"id":"word_choice_30","concept":"word_choice","level":"B1","options":["My sister is very sensed.","My sister is very sensitive.","My sister is very sensible."],"answerIndex":1,"explain":"sensitive = wrażliwy; sensible = rozsądny.","prompt":"You want to say your sister's feelings are easily hurt (wrażliwa). Which is right?"},{"id":"questions_negation_0","concept":"questions_negation","level":"B1","options":["You're coming, aren't you?","You're coming, no yes?","You're coming, isn't it?"],"answerIndex":0,"explain":"Question tags mirror the verb: you're → aren't you?"},{"id":"questions_negation_12","concept":"questions_negation","level":"B1","options":["Neither I do.","Either do I not.","Neither do I."],"answerIndex":2,"explain":"Agreement with negatives: Neither do I / Me neither."},{"id":"articles_31","concept":"articles","level":"B2","options":["Rich should help poor.","The rich should help the poor.","A rich should help a poor."],"answerIndex":1,"explain":"'the + adjective' = the group: the rich, the young."},{"id":"verb_tense_2","concept":"verb_tense","level":"B2","options":["This time next week I will lying on a beach.","This time next week I will be lying on a beach.","This time next week I am lie on a beach."],"answerIndex":1,"explain":"Action in progress at a future moment: will be + -ing."},{"id":"subject_verb_9","concept":"subject_verb","level":"B2","options":["A number of students was late.","A number of student were late.","A number of students were late."],"answerIndex":2,"explain":"'A number of' + plural verb; 'the number of' + singular."},{"id":"prepositions_19","concept":"prepositions","level":"B2","options":["She insisted for paying.","She insisted to pay.","She insisted on paying."],"answerIndex":2,"explain":"insist ON + -ing."},{"id":"word_order_12","concept":"word_order","level":"B2","options":["Never have I seen such a mess.","Never seen I have such a mess.","Never I have seen such a mess."],"answerIndex":0,"explain":"After 'never/rarely' at the start, invert: Never have I…"},{"id":"modals_7","concept":"modals","level":"B2","options":["She must missed the train.","She must had missed the train.","She must have missed the train."],"answerIndex":2,"explain":"Past deduction: must have + participle."},{"id":"conditionals_1","concept":"conditionals","level":"B2","options":["If she had studied, she would have passed.","If she had studied, she would passed.","If she would have studied, she would have passed."],"answerIndex":0,"explain":"Third conditional: if + had + participle, would have + participle."},{"id":"conditionals_5","concept":"conditionals","level":"B2","options":["I wish I knew the answer.","I wish I would knew the answer.","I wish I know the answer."],"answerIndex":0,"explain":"wish + past for present regrets: I wish I knew."},{"id":"gerund_infinitive_6","concept":"gerund_infinitive","level":"B2","options":["I remember to lock the door yesterday.","I remember locking the door.","I remember lock the door yesterday."],"answerIndex":1,"explain":"remember + -ing = memory of doing; remember + to = duty."},{"id":"collocation_4","concept":"collocation","level":"B2","options":["The medicine makes effect after an hour.","The medicine takes effect after an hour.","The medicine does effect after an hour."],"answerIndex":1,"explain":"TAKE effect; but MAKE an impression."},{"id":"word_choice_20","concept":"word_choice","level":"B2","options":["The lecture was quite bored.","The lecture was quite boringed.","The lecture was quite boring."],"answerIndex":2,"explain":"-ing describes the thing (boring lecture); -ed describes the feeling (bored student)."},{"id":"prepositions_40","concept":"prepositions","level":"A2","options":["Your opinion is very important for me.","Your opinion is very important to me.","Your opinion is very important at me."],"answerIndex":1,"explain":"When something matters to a person's feelings, English says 'important TO me'. Polish 'ważne dla mnie' pulls learners toward 'for'. ('Important FOR' = good for a purpose: 'Sleep is important for your health.')"},{"id":"prepositions_41","concept":"prepositions","level":"B1","options":["Sleep is important to your health.","Sleep is important for your health.","Sleep is important with your health."],"answerIndex":1,"explain":"'Important FOR' = necessary or good for a purpose or benefit: for your health, for the exam. 'Important TO' = it matters to a person."},{"id":"conditionals_10","concept":"conditionals","level":"A2","options":["If I will see him, I will tell him.","If I see him, I will tell him.","If I would see him, I will tell him."],"answerIndex":1,"explain":"First conditional: if + present simple, will + verb. Polish puts the future in both halves ('jeśli go zobaczę'); English never puts 'will' after 'if'."},{"id":"conditionals_11","concept":"conditionals","level":"B1","options":["If I was you, I would took the job.","If I were you, I would take the job.","If I would be you, I would take the job."],"answerIndex":1,"explain":"Second conditional advice: If I were you, I would take… 'would' never goes inside the if-clause."},{"id":"conditionals_12","concept":"conditionals","level":"B2","options":["If you had told me, I would help you.","If you had told me, I would have helped you.","If you would have told me, I would have helped you."],"answerIndex":1,"explain":"Third conditional (a past regret): if + had + participle, would have + participle."},{"id":"comparatives_10","concept":"comparatives","level":"A1","options":["This phone is the most cheap in the shop.","This phone is the cheapest in the shop.","This phone is cheapest than the others."],"answerIndex":1,"explain":"One-syllable adjectives take -est for the superlative: the cheapest. Comparing two things uses -er + than: cheaper than."},{"id":"comparatives_11","concept":"comparatives","level":"A2","options":["Warsaw is much bigger as Kraków.","Warsaw is much bigger than Kraków.","Warsaw is much more bigger than Kraków."],"answerIndex":1,"explain":"bigger THAN (Polish 'niż'). Never 'more' and '-er' together."}]};
